package in.recallradar;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class InventoryServiceTest { @Autowired InventoryService inventory; @Autowired TenantService tenants; @Autowired UserRepository users; @Autowired MembershipRepository memberships; @Autowired LocationRepository locations; @Autowired SupplierRepository suppliers; @Autowired IngredientRepository ingredients; @Autowired StockMovementRepository movements; @Autowired AuditEventRepository auditEvents;
 @Test void ledgerCalculatesBalancesAndPreventsNegativeStock(){var user=users.save(new AppUser("Inventory Tester","inventory@test.example","hash"));var org=tenants.createWorkspace(user,"Inventory Test Kitchens");var membership=memberships.findByUserIdAndOrganizationId(user.id,org.id).orElseThrow();var warehouse=locations.save(new Location(org.id,"Warehouse",LocationType.WAREHOUSE,"Hyderabad"));var outlet=locations.save(new Location(org.id,"Outlet",LocationType.OUTLET,"Hyderabad"));var supplier=suppliers.save(new Supplier(org.id,"Supplier",null,null,null));var ingredient=ingredients.save(new Ingredient(org.id,"Rice","Grain","kg"));var received=inventory.receive(membership,new ReceiveLotRequest(ingredient.id,supplier.id,"RICE-001",null,null,warehouse.id,new BigDecimal("100"),"kg",null));assertEquals(0,new BigDecimal("100").compareTo(received.totalQuantity()));var transferred=inventory.transfer(membership,java.util.UUID.fromString(received.lot().id()),new TransferRequest(warehouse.id,outlet.id,new BigDecimal("35"),"Transfer"));assertEquals(0,new BigDecimal("100").compareTo(transferred.totalQuantity()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->inventory.transfer(membership,java.util.UUID.fromString(received.lot().id()),new TransferRequest(outlet.id,warehouse.id,new BigDecimal("36"),"Too much")));var waste=inventory.reduce(membership,java.util.UUID.fromString(received.lot().id()),new StockReductionRequest(outlet.id,new BigDecimal("5"),"Spoiled"),MovementType.WASTE);assertEquals(0,new BigDecimal("95").compareTo(waste.totalQuantity()));assertEquals(2,waste.balances().size());}
 @Test void repeatedIdempotencyKeyDoesNotCreateAnotherMovement(){var user=users.save(new AppUser("Idempotency Tester","idempotency@test.example","hash"));var org=tenants.createWorkspace(user,"Idempotency Kitchens");var member=memberships.findByUserIdAndOrganizationId(user.id,org.id).orElseThrow();var warehouse=locations.save(new Location(org.id,"Warehouse",LocationType.WAREHOUSE,"Hyderabad"));var supplier=suppliers.save(new Supplier(org.id,"Supplier",null,null,null));var ingredient=ingredients.save(new Ingredient(org.id,"Flour","Grain","kg"));var lot=inventory.receive(member,new ReceiveLotRequest(ingredient.id,supplier.id,"FLOUR-1",null,null,warehouse.id,new BigDecimal("10"),"kg",null));var id=java.util.UUID.fromString(lot.lot().id());inventory.adjust(member,id,new AdjustmentRequest(warehouse.id,new BigDecimal("2"),"Counted"),"same-request");var repeated=inventory.adjust(member,id,new AdjustmentRequest(warehouse.id,new BigDecimal("2"),"Counted"),"same-request");assertEquals(0,new BigDecimal("12").compareTo(repeated.totalQuantity()));assertEquals(2,movements.findByLotIdOrderByOccurredAt(id).size());assertEquals(2,auditEvents.findTop20ByOrganizationIdOrderByOccurredAtDesc(org.id).size());}
}
